/**
 * templates.ts — Setup templates (.pulse files) and letter templates.
 *
 * Setup templates encode grid structure (columns, alert rules, checklist templates)
 * as a portable .pulse JSON file — no client data, structure only.
 *
 * Letter templates use {{placeholder}} syntax and are generated by filling
 * placeholders from client row data.
 */

import { startingWidth } from '../shared/columnTypes'
import { columnTypesWhere } from '../shared/columnTraits'
import fs from 'fs'
import { z } from 'zod'
import { textLength } from '../shared/textLength'
import { getDb } from './database'
import { logger } from './logger'
import { usesHumanServicesWords } from './vocab'
import { freshAutoNumberConfig } from './auto-number'
import { buildSafeSetClause, logNonFatal, assertSafePath } from './ipc/ipc-utils'
import type { Column, ChecklistTemplate, AlertRule } from '../shared/types'
import { RULE_KINDS, type RuleKind } from '../shared/deadlineEngine'
import { linkColumnRules, portableRuleFields, refersToColumns, resolveRuleFields } from './rule-columns'

// ──────────────────────────────────────────────────────────────────────────────
// .pulse file format
// ──────────────────────────────────────────────────────────────────────────────

export interface PulseTemplateColumn {
  name: string
  column_type: string
  width?: number
  position: number
  is_name_column?: number
  is_identifier?: number
  /** Empty cells show "Missing"; left out when not required */
  is_required?: number
  default_value?: string | null
  description?: string | null
  config?: string
  // Degradation tracking
  original_type?: string
  degraded_from?: string
}

export interface PulseTemplateAlertRule {
  name: string
  description?: string | null
  thresholds: string  // JSON
  interval_days?: number | null
  interval_months?: number | null
  end_of_month?: number | null
  /** W05 kinds (absent = a plain date rule); settings name columns, see rule-columns.ts */
  kind?: RuleKind
  rule_config?: string | null
  rule_condition?: string | null
  business_days?: number
}

export interface PulseTemplateChecklist {
  name: string
  description?: string | null
  items: string  // JSON array
  is_recurring?: number
  recurrence_days?: number | null
}

export interface PulseFile {
  pulse_template: string  // semver e.g. '1.0'
  type: 'setup'
  name: string
  description?: string
  author?: string
  created: string  // YYYY-MM-DD
  columns: PulseTemplateColumn[]
  alert_rules: PulseTemplateAlertRule[]
  checklists: PulseTemplateChecklist[]
}

// ──────────────────────────────────────────────────────────────────────────────
// Zod schema for .pulse file validation
// ──────────────────────────────────────────────────────────────────────────────

const MAX_PULSE_FILE_BYTES = 10 * 1024 * 1024  // 10 MB
const MAX_COLUMNS = 100
const MAX_ALERT_RULES = 50
const MAX_CHECKLISTS = 50
const MAX_STRING_LEN = 1000
const MAX_JSON_FIELD_LEN = 10_000  // config / thresholds / items JSON

/** Validates that a string is parseable JSON */
const jsonString = (maxLen: number) => z.string().check(textLength({ max: maxLen })).refine(
  (s) => { try { JSON.parse(s); return true } catch (err) { logNonFatal('templates', 'jsonString validation parse', err); return false } },
  { message: 'Must be valid JSON' }
)

/** Validates that thresholds JSON is an array of {daysBefore, bgClass, label} objects */
const thresholdsJson = z.string().check(textLength({ max: MAX_JSON_FIELD_LEN })).refine(
  (s) => {
    try {
      const arr = JSON.parse(s)
      if (!Array.isArray(arr)) return false
      return arr.every((t: unknown) =>
        typeof t === 'object' && t !== null &&
        typeof (t as Record<string, unknown>).daysBefore === 'number' &&
        typeof (t as Record<string, unknown>).bgClass === 'string' &&
        typeof (t as Record<string, unknown>).label === 'string'
      )
    } catch (err) { logNonFatal('templates', 'thresholdsJson validation parse', err); return false }
  },
  { message: 'Must be a valid JSON array of AlertThreshold objects ({daysBefore, bgClass, label})' }
)

/** Validates that items JSON is a flat array of strings or objects with a title field */
const checklistItemsJson = z.string().check(textLength({ max: MAX_JSON_FIELD_LEN })).refine(
  (s) => {
    try {
      const arr = JSON.parse(s)
      return Array.isArray(arr) && arr.every((i: unknown) =>
        typeof i === 'string' ||
        (typeof i === 'object' && i !== null && typeof (i as Record<string, unknown>).title === 'string')
      )
    } catch (err) { logNonFatal('templates', 'checklistItemsJson validation parse', err); return false }
  },
  { message: 'Must be a valid JSON array of checklist items' }
)

const PulseColumnSchema = z.object({
  name: z.string().check(textLength({ min: 1, max: MAX_STRING_LEN })),
  column_type: z.string().check(textLength({ min: 1, max: 100 })),
  width: z.number().int().min(30).max(2000).optional(),
  position: z.number().int().min(0).max(MAX_COLUMNS),
  is_name_column: z.union([z.literal(0), z.literal(1)]).optional(),
  is_identifier: z.union([z.literal(0), z.literal(1)]).optional(),
  is_required: z.union([z.literal(0), z.literal(1)]).optional(),
  default_value: z.string().check(textLength({ max: MAX_STRING_LEN })).nullable().optional(),
  description: z.string().check(textLength({ max: MAX_STRING_LEN })).nullable().optional(),
  config: jsonString(MAX_JSON_FIELD_LEN).optional(),
  original_type: z.string().check(textLength({ max: 100 })).optional(),
  degraded_from: z.string().check(textLength({ max: 100 })).optional(),
}).strict()

const PulseAlertRuleSchema = z.object({
  name: z.string().check(textLength({ min: 1, max: MAX_STRING_LEN })),
  description: z.string().check(textLength({ max: MAX_STRING_LEN })).nullable().optional(),
  thresholds: thresholdsJson,
  interval_days: z.number().int().min(0).max(3650).nullable().optional(),
  interval_months: z.number().int().min(0).max(120).nullable().optional(),
  end_of_month: z.number().int().min(0).max(1).nullable().optional(),
  kind: z.enum(RULE_KINDS).optional(),
  rule_config: jsonString(MAX_JSON_FIELD_LEN).nullable().optional(),
  rule_condition: jsonString(2_000).nullable().optional(),
  business_days: z.union([z.literal(0), z.literal(1)]).optional(),
}).strict()

const PulseChecklistSchema = z.object({
  name: z.string().check(textLength({ min: 1, max: MAX_STRING_LEN })),
  description: z.string().check(textLength({ max: MAX_STRING_LEN })).nullable().optional(),
  items: checklistItemsJson,
  is_recurring: z.union([z.literal(0), z.literal(1)]).optional(),
  recurrence_days: z.number().int().min(1).max(3650).nullable().optional(),
}).strict()

const PulseFileSchema = z.object({
  pulse_template: z.string().check(textLength({ min: 1, max: 20 })),
  type: z.literal('setup'),
  name: z.string().check(textLength({ min: 1, max: MAX_STRING_LEN })),
  description: z.string().check(textLength({ max: MAX_STRING_LEN })).optional(),
  author: z.string().check(textLength({ max: MAX_STRING_LEN })).optional(),
  created: z.string().check(textLength({ max: 20 })),
  columns: z.array(PulseColumnSchema).max(MAX_COLUMNS),
  alert_rules: z.array(PulseAlertRuleSchema).max(MAX_ALERT_RULES),
  checklists: z.array(PulseChecklistSchema).max(MAX_CHECKLISTS),
}).strict()

// Known column types that this version supports
const KNOWN_COLUMN_TYPES = new Set<string>(columnTypesWhere(t => t.inTemplates))

/**
 * Validate a JSON string as a PulseFile. Used by IPC handlers that receive
 * pulse data from the renderer (e.g. SETUP_TEMPLATE_APPLY).
 * Throws with a descriptive message if validation fails.
 */
export function validatePulseJson(json: string): PulseFile {
  let parsed: unknown
  try { parsed = JSON.parse(json) } catch (err) {
    logNonFatal('templates', 'validatePulseJson parse', err)
    throw new Error('Invalid JSON in pulse template data')
  }
  const result = PulseFileSchema.safeParse(parsed)
  if (!result.success) {
    const issues = result.error.issues.slice(0, 3).map(i => `  ${i.path.join('.')}: ${i.message}`)
    throw new Error(`Invalid pulse template:\n${issues.join('\n')}`)
  }
  return result.data as PulseFile
}

// ──────────────────────────────────────────────────────────────────────────────
// Setup Templates — CRUD (stored in setup_templates table)
// ──────────────────────────────────────────────────────────────────────────────

export interface SetupTemplate {
  id: number
  name: string
  description: string | null
  pulse_json: string  // JSON: PulseFile
  is_system: 0 | 1
  created_at: string
}

export function getSetupTemplates(): SetupTemplate[] {
  const db = getDb()
  const sql = 'SELECT id, name, description, template_data AS pulse_json, is_system, created_at FROM setup_templates ORDER BY is_system DESC, name ASC'
  // Seed or update the built-in templates when this version ships new ones.
  // Pre-versioning installs that already seeded count as version 1.
  const versionRow = db.prepare("SELECT value FROM app_meta WHERE key = 'setup_templates_version'").get() as { value: string } | undefined
  const legacySeeded = db.prepare("SELECT 1 FROM app_meta WHERE key = 'setup_templates_seeded'").get()
  const seededVersion = versionRow ? Number(versionRow.value) : legacySeeded ? 1 : 0
  // The built-ins are human-services lists; other workspaces get theirs from the example gallery
  if (seededVersion < BUILTIN_TEMPLATES_VERSION && usesHumanServicesWords()) {
    syncBuiltInSetupTemplates(seededVersion)
    db.prepare("INSERT OR REPLACE INTO app_meta (key, value) VALUES ('setup_templates_version', ?)").run(String(BUILTIN_TEMPLATES_VERSION))
    db.prepare("INSERT OR REPLACE INTO app_meta (key, value) VALUES ('setup_templates_seeded', '1')").run()
  }

  return db.prepare(sql).all() as SetupTemplate[]
}

export function createSetupTemplate(name: string, description: string | null, pulseJson: string): number {
  // Validate JSON structure before saving (fail fast instead of at apply time)
  validatePulseJson(pulseJson)
  const result = getDb().prepare(`
    INSERT INTO setup_templates (name, description, template_data, is_system, created_at)
    VALUES (?, ?, ?, 0, datetime('now'))
  `).run(name, description ?? null, pulseJson)
  return result.lastInsertRowid as number
}

export function deleteSetupTemplate(id: number): void {
  getDb().prepare('DELETE FROM setup_templates WHERE id = ?').run(id)
}

// ──────────────────────────────────────────────────────────────────────────────
// Export current grid as .pulse file
// ──────────────────────────────────────────────────────────────────────────────

export function exportGridAsPulse(gridId: number): PulseFile {
  const db = getDb()
  const grid = db.prepare('SELECT * FROM grids WHERE id = ?').get(gridId) as { name: string; description: string | null }
  const columns = db.prepare('SELECT * FROM columns WHERE grid_id = ? ORDER BY position').all(gridId) as Column[]
  // Columns refer to rules by id, which means nothing in another database:
  // record the rule's name in the config and export only the rules this grid uses.
  const ruleById = new Map((db.prepare('SELECT * FROM alert_rules WHERE is_system = 0').all() as AlertRule[]).map(r => [r.id, r]))
  const usedRuleIds = new Set<number>()
  const checklistById = new Map((db.prepare('SELECT id, name FROM checklist_templates').all() as Array<{ id: number; name: string }>).map(c => [c.id, c]))
  const columnNameById = new Map(columns.map(c => [c.id, c.name]))
  const exportConfig = (config: string): string => {
    try {
      const cfg = JSON.parse(config || '{}') as Record<string, unknown>
      // Age and Days-until read another column; by name, since its id means nothing elsewhere
      if ('source_column_id' in cfg) {
        const source = typeof cfg.source_column_id === 'number' ? columnNameById.get(cfg.source_column_id) : undefined
        if (source !== undefined) cfg.source_column_name = source
        delete cfg.source_column_id
      }
      const rule = typeof cfg.alert_rule_id === 'number' ? ruleById.get(cfg.alert_rule_id) : undefined
      if (rule) { cfg.alert_rule_name = rule.name; usedRuleIds.add(rule.id) }
      const checklist = typeof cfg.done_checklist_id === 'number' ? checklistById.get(cfg.done_checklist_id) : undefined
      if (checklist) cfg.done_checklist_name = checklist.name
      // The stage's checklist and date column by name (W06 §8)
      if ('stage' in cfg) {
        const stage = stageConfigOf({ column_type: 'status', config: JSON.stringify({ stage: cfg.stage }) })
        if (stage) cfg.stage_portable = portableStage(stage, db, gridId)
        delete cfg.stage
      }
      return JSON.stringify(cfg)
    } catch { return config }
  }
  // A setup file holds one list, so it can't hold links between lists (W04 §8)
  const exportedColumns = columns.filter(col => col.column_type !== 'link').map((col, i) => ({
    name: col.name,
    column_type: col.column_type,
    width: col.width,
    position: i,
    is_name_column: col.is_name_column,
    is_identifier: col.is_identifier,
    ...(col.is_required ? { is_required: 1 } : {}),
    default_value: col.default_value,
    description: col.description,
    config: exportConfig(col.config)
  }))
  const alertRules = [...usedRuleIds].map(id => ruleById.get(id)!).sort((a, b) => a.name.localeCompare(b.name))
  const checklistTemplates = db.prepare('SELECT * FROM checklist_templates ORDER BY name').all() as ChecklistTemplate[]

  return {
    pulse_template: '1.0',
    type: 'setup',
    name: grid.name,
    description: grid.description || undefined,
    created: localDateString(),
    columns: exportedColumns,
    alert_rules: alertRules.map(r => ({
      name: r.name,
      description: r.description,
      thresholds: r.thresholds,
      interval_days: r.interval_days,
      interval_months: r.interval_months ?? null,
      end_of_month: r.end_of_month ?? 0,
      ...portableRuleFields(r, id => columns.find(c => c.id === id)?.name),
    })),
    checklists: checklistTemplates.map(t => ({
      name: t.name,
      description: t.description,
      items: t.items,
      is_recurring: t.is_recurring,
      recurrence_days: t.recurrence_days
    }))
  }
}

export function writePulseFile(pulseFile: PulseFile, destPath: string): void {
  if (!destPath.endsWith('.pulse')) {
    throw new Error('A template file needs the .pulse extension. Choose a name that ends in .pulse.')
  }
  // The same rule as every other file Pulse writes: USB drives, second drives and folders
  // picked in a dialog are fine, system folders aren't. A home-or-data-folder check here
  // refused a USB drive and showed the raw path (F-034).
  assertSafePath(destPath)
  // Atomic write to prevent corruption on power loss or disk-full
  const { writeFileSync: ws, openSync, fsyncSync, closeSync, unlinkSync, renameSync } = require('fs') as typeof import('fs')
  const tmp = destPath + '.tmp'
  try {
    ws(tmp, JSON.stringify(pulseFile, null, 2), 'utf-8')
    const fd = openSync(tmp, 'r+')
    try { fsyncSync(fd) } finally { closeSync(fd) }
    renameSync(tmp, destPath)
  } catch (err) {
    try { unlinkSync(tmp) } catch (err2) { logNonFatal('templates', 'writePulseFile cleanup tmp', err2) }
    throw err
  }
}

// ──────────────────────────────────────────────────────────────────────────────
// Import .pulse file
// ──────────────────────────────────────────────────────────────────────────────

export interface PulseImportPreview {
  name: string
  description?: string
  columnCount: number
  alertRuleCount: number
  checklistCount: number
  columns: Array<{ name: string; column_type: string; degraded?: boolean }>
  warnings: string[]
}

/** Whether a .pulse file is a single-list setup (v1) or a workspace template (v2) */
export async function readPulseKind(filePath: string): Promise<'setup' | 'workspace' | 'unknown'> {
  try {
    // eslint-disable-next-line security/detect-non-literal-fs-filename
    const stat = await fs.promises.stat(filePath)
    if (stat.size > MAX_PULSE_FILE_BYTES) return 'unknown'
    // eslint-disable-next-line security/detect-non-literal-fs-filename
    const type = (JSON.parse(await fs.promises.readFile(filePath, 'utf-8')) as { type?: unknown } | null)?.type
    return type === 'setup' || type === 'workspace' ? type : 'unknown'
  } catch { return 'unknown' }
}

export async function parsePulseFile(filePath: string): Promise<{ pulse: PulseFile; preview: PulseImportPreview }> {
  // Check existence and size via stat (async)
  let fileSize: number
  try {
    const stat = await fs.promises.stat(filePath)
    fileSize = stat.size
  } catch (err) {
    logNonFatal('templates', 'parsePulseFile stat', err)
    throw new Error('File not found')
  }

  // Guard against oversized files (DoS prevention)
  if (fileSize > MAX_PULSE_FILE_BYTES) {
    throw new Error(`Template file is too large (${Math.round(fileSize / 1024 / 1024)}MB). Maximum size is ${MAX_PULSE_FILE_BYTES / 1024 / 1024}MB.`)
  }

  const raw = await fs.promises.readFile(filePath, 'utf-8')

  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch (err) {
    logNonFatal('templates', 'parsePulseFile JSON parse', err)
    throw new Error('File is not valid JSON. This may not be a .pulse template file.')
  }

  if (parsed && typeof parsed === 'object' && (parsed as { type?: unknown }).type === 'workspace') {
    throw new Error('This is a workspace template. Open it from Settings → Workspace → Open a template file.')
  }

  // Validate structure with Zod
  const result = PulseFileSchema.safeParse(parsed)
  if (!result.success) {
    const issues = result.error.issues.slice(0, 3).map(i => `  ${i.path.join('.')}: ${i.message}`)
    throw new Error(`Invalid .pulse template file:\n${issues.join('\n')}`)
  }
  const pulse = result.data as PulseFile

  const warnings: string[] = []
  const processedColumns = pulse.columns.map(col => {
    const isDegraded = !KNOWN_COLUMN_TYPES.has(col.column_type)
    if (isDegraded) {
      warnings.push(`Column "${col.name}": type "${col.column_type}" is not recognized — will be imported as "text"`)
    }
    return {
      name: col.name,
      column_type: isDegraded ? 'text' : col.column_type,
      degraded: isDegraded
    }
  })

  // Check template version compatibility
  const templateMajor = parseInt(pulse.pulse_template.split('.')[0] ?? '1')
  if (templateMajor > 1) {
    warnings.push(`This template was created with a newer version of Pulse (v${pulse.pulse_template}). Some features may not be available.`)
  }

  return {
    pulse,
    preview: {
      name: pulse.name,
      description: pulse.description,
      columnCount: pulse.columns.length,
      alertRuleCount: pulse.alert_rules.length,
      checklistCount: pulse.checklists.length,
      columns: processedColumns,
      warnings
    }
  }
}

/**
 * Create (or reuse, by name) the template's alert rules. Returns name → id.
 * Rules that point at columns wait for the columns (linkColumnRules).
 */
function importAlertRules(db: ReturnType<typeof getDb>, rules: PulseTemplateAlertRule[]): Map<string, number> {
  const ids = new Map<string, number>()
  for (const rule of rules) {
    if (refersToColumns(rule)) continue
    const f = resolveRuleFields(rule, () => undefined).fields
    const existing = db.prepare('SELECT id FROM alert_rules WHERE name = ?').get(rule.name) as { id: number } | undefined
    const id = existing?.id ?? Number(db.prepare(`
      INSERT INTO alert_rules (name, description, is_system, thresholds, interval_days, interval_months, end_of_month,
        kind, rule_config, rule_condition, business_days, created_at)
      VALUES (?, ?, 0, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
    `).run(rule.name, rule.description ?? null, rule.thresholds, rule.interval_days ?? null,
      rule.interval_months ?? null, rule.end_of_month ? 1 : 0, f.kind, f.rule_config, f.rule_condition, f.business_days).lastInsertRowid)
    ids.set(rule.name, id)
  }
  return ids
}

/**
 * Point a template column at the right alert rule in THIS database.
 * New files carry alert_rule_name; older files only have an id from the
 * database that made the file, which is kept only if such a rule exists here.
 */
/** Create the template's checklist templates (an existing one with the same name is kept). */
function importChecklistTemplates(db: ReturnType<typeof getDb>, checklists: PulseTemplateChecklist[]): void {
  for (const cl of checklists) {
    const existing = db.prepare('SELECT id FROM checklist_templates WHERE name = ?').get(cl.name)
    if (!existing) {
      db.prepare(`
        INSERT INTO checklist_templates (name, description, items, is_recurring, recurrence_days, is_system, created_at)
        VALUES (?, ?, ?, ?, ?, 0, datetime('now'))
      `).run(cl.name, cl.description ?? null, cl.items, cl.is_recurring ?? 0, cl.recurrence_days ?? null)
    }
  }
}

function linkColumnConfig(db: ReturnType<typeof getDb>, config: string, ruleIds: Map<string, number>, later: Set<string>): string {
  let cfg: Record<string, unknown>
  try { cfg = JSON.parse(config || '{}') as Record<string, unknown> } catch { return '{}' }
  // Ids from another database; a stage is set up by name afterwards (applyFileStage)
  delete cfg.stage
  if (typeof cfg.alert_rule_name === 'string' && later.has(cfg.alert_rule_name)) {
    delete cfg.alert_rule_id
  } else if (typeof cfg.alert_rule_name === 'string') {
    const id = ruleIds.get(cfg.alert_rule_name)
      ?? (db.prepare('SELECT id FROM alert_rules WHERE name = ?').get(cfg.alert_rule_name) as { id: number } | undefined)?.id
    if (id) cfg.alert_rule_id = id
    else delete cfg.alert_rule_id
  } else if (cfg.alert_rule_id !== undefined && !db.prepare('SELECT 1 FROM alert_rules WHERE id = ?').get(cfg.alert_rule_id)) {
    delete cfg.alert_rule_id
  }
  // Same for the "when marked done, add checklist" link
  if (typeof cfg.done_checklist_name === 'string') {
    const cl = db.prepare('SELECT id FROM checklist_templates WHERE name = ?').get(cfg.done_checklist_name) as { id: number } | undefined
    if (cl) cfg.done_checklist_id = cl.id
    else delete cfg.done_checklist_id
  } else if (cfg.done_checklist_id !== undefined && !db.prepare('SELECT 1 FROM checklist_templates WHERE id = ?').get(cfg.done_checklist_id)) {
    delete cfg.done_checklist_id
  }
  return JSON.stringify(cfg)
}

/**
 * Age and Days-until columns from a file or starter name the column they read
 * (`source_column_name`); point them at this list's column of that name. An id
 * from an older file belonged to the database that made it, so it's only kept
 * when it is one of this list's columns. An Age column left with no source
 * falls back to the list's birth-date column.
 */
export function linkSourceColumns(db: ReturnType<typeof getDb>, gridId: number): void {
  const cols = db.prepare('SELECT id, name, column_type, config FROM columns WHERE grid_id = ? ORDER BY position, id').all(gridId) as
    Array<{ id: number; name: string; column_type: string; config: string | null }>
  const byName = new Map<string, number>()
  for (const c of cols) if (!byName.has(c.name.trim().toLowerCase())) byName.set(c.name.trim().toLowerCase(), c.id)
  const ownIds = new Set(cols.map(c => c.id))
  const birthColumn = cols.find(c => c.column_type === 'date' && looksLikeBirthColumn(c.name))?.id
  const update = db.prepare('UPDATE columns SET config = ? WHERE id = ?')
  for (const c of cols) {
    if (c.column_type !== 'age_from_dob' && c.column_type !== 'calculated_days') continue
    let cfg: Record<string, unknown>
    try { cfg = JSON.parse(c.config || '{}') as Record<string, unknown> } catch { continue }
    if (!cfg || typeof cfg !== 'object' || Array.isArray(cfg)) continue
    const before = JSON.stringify(cfg)
    if (typeof cfg.source_column_name === 'string') {
      const id = byName.get(cfg.source_column_name.trim().toLowerCase())
      if (id !== undefined) cfg.source_column_id = id
      else delete cfg.source_column_id
      delete cfg.source_column_name
    } else if (cfg.source_column_id !== undefined && !(typeof cfg.source_column_id === 'number' && ownIds.has(cfg.source_column_id))) {
      delete cfg.source_column_id
    }
    if (cfg.source_column_id === undefined && c.column_type === 'age_from_dob' && birthColumn !== undefined) cfg.source_column_id = birthColumn
    const after = JSON.stringify(cfg)
    if (after !== before) update.run(after, c.id)
  }
}

/** A file column's stage (by names) becomes the list's stage */
function applyFileStage(db: ReturnType<typeof getDb>, gridId: number, listName: string): void {
  const cols = db.prepare("SELECT id, name, config FROM columns WHERE grid_id = ? AND json_extract(config, '$.stage_portable') IS NOT NULL").all(gridId) as Array<{ id: number; name: string; config: string }>
  for (const c of cols) {
    const cfg = JSON.parse(c.config) as Record<string, unknown>
    const parsed = portableStageSchema.safeParse(cfg.stage_portable)
    delete cfg.stage_portable
    db.prepare('UPDATE columns SET config = ? WHERE id = ?').run(JSON.stringify(cfg), c.id)
    if (parsed.success && c === cols[0]) for (const w of applyPortableStage(db, gridId, listName, c.name, parsed.data)) logger.warn('templates', w)
  }
}

/**
 * Apply a .pulse template to create a new grid.
 * Returns the new grid ID.
 */
export function applyPulseToNewGrid(pulse: PulseFile): number {
  const db = getDb()

  return db.transaction(() => {
    // Create grid
    const gridResult = db.prepare(`
      INSERT INTO grids (name, description, created_at, updated_at)
      VALUES (?, ?, datetime('now'), datetime('now'))
    `).run(pulse.name, pulse.description ?? null)
    const gridId = gridResult.lastInsertRowid as number

    // Rules first, so columns can be linked to them by name
    const ruleIds = importAlertRules(db, pulse.alert_rules)
    const later = new Set(pulse.alert_rules.filter(refersToColumns).map(r => r.name))
    importChecklistTemplates(db, pulse.checklists)

    // Create columns
    for (const col of pulse.columns) {
      const colType = KNOWN_COLUMN_TYPES.has(col.column_type) ? col.column_type : 'text'
      const config = (() => {
        if (!KNOWN_COLUMN_TYPES.has(col.column_type) && col.column_type) {
          // Record original type in config for future reference
          const existingConfig = col.config ? JSON.parse(col.config) : {}
          return JSON.stringify({ ...existingConfig, original_type: col.column_type, degraded_from: col.column_type })
        }
        // A new list numbers from 1, whatever the list it came from had reached
        return colType === 'auto_number' ? freshAutoNumberConfig(col.config) : col.config || '{}'
      })()

      db.prepare(`
        INSERT INTO columns (grid_id, name, column_type, width, position, is_name_column, is_identifier, is_required,
          default_value, description, config, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
      `).run(
        gridId, col.name, colType, startingWidth(colType, col.config, col.width, { name: col.name, isName: col.is_name_column === 1 }), col.position,
        col.is_name_column ?? 0, col.is_identifier ?? 0, col.is_required && canBeRequired(colType) ? 1 : 0,
        col.default_value ?? null, col.description ?? null, linkColumnConfig(db, config, ruleIds, later)
      )
    }
    for (const w of linkColumnRules(db, gridId, pulse.name, pulse.alert_rules, {})) logger.warn('templates', w)
    linkSourceColumns(db, gridId)
    applyFileStage(db, gridId, pulse.name)

    return gridId
  })() as number
}

/**
 * Apply a .pulse template to an existing grid (add columns, merge alert rules).
 */
export function applyPulseToExistingGrid(pulse: PulseFile, gridId: number): void {
  const db = getDb()

  db.transaction(() => {
    const maxPos = (db.prepare('SELECT MAX(position) as p FROM columns WHERE grid_id = ?').get(gridId) as { p: number | null }).p ?? -1
    let nextPos = maxPos + 1
    const ruleIds = importAlertRules(db, pulse.alert_rules)
    const later = new Set(pulse.alert_rules.filter(refersToColumns).map(r => r.name))
    importChecklistTemplates(db, pulse.checklists)

    for (const col of pulse.columns) {
      const colType = KNOWN_COLUMN_TYPES.has(col.column_type) ? col.column_type : 'text'
      // Only add columns that don't already exist (by name)
      const existing = db.prepare('SELECT id FROM columns WHERE grid_id = ? AND name = ?').get(gridId, col.name)
      if (!existing) {
        db.prepare(`
          INSERT INTO columns (grid_id, name, column_type, width, position, is_name_column, is_identifier, is_required,
            default_value, description, config, created_at)
          VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, datetime('now'))
        `).run(gridId, col.name, colType, startingWidth(colType, col.config, col.width, { name: col.name }), nextPos++, col.is_required && canBeRequired(colType) ? 1 : 0, col.default_value ?? null, col.description ?? null,
          linkColumnConfig(db, colType === 'auto_number' ? freshAutoNumberConfig(col.config) : col.config || '{}', ruleIds, later))
      }
    }
    // Rules that point at columns resolve against this list's columns, new and existing
    const listName = (db.prepare('SELECT name FROM grids WHERE id = ?').get(gridId) as { name: string } | undefined)?.name ?? pulse.name
    for (const w of linkColumnRules(db, gridId, listName, pulse.alert_rules, {})) logger.warn('templates', w)
    linkSourceColumns(db, gridId)
    // A list keeps the stage it has; a file's stage only lands on a list without one
    if (!stageColumnOf(db.prepare('SELECT column_type, config FROM columns WHERE grid_id = ?').all(gridId) as Array<{ column_type: string; config: string | null }>)) applyFileStage(db, gridId, listName)
    else db.prepare("UPDATE columns SET config = json_remove(config, '$.stage_portable') WHERE grid_id = ? AND json_extract(config, '$.stage_portable') IS NOT NULL").run(gridId)
  })()
}

// ──────────────────────────────────────────────────────────────────────────────
// Pre-built setup templates seed
// ──────────────────────────────────────────────────────────────────────────────

/**
 * Insert/update built-in templates. Templates that already exist (by name, as
 * built-ins) are updated in place; templates new since `fromVersion` are added;
 * built-ins the user deleted are not brought back.
 */
function syncBuiltInSetupTemplates(fromVersion: number): void {
  const db = getDb()

  const templates = builtinSetupTemplates()

  const findExisting = db.prepare('SELECT id FROM setup_templates WHERE name = ? AND is_system = 1')
  const update = db.prepare('UPDATE setup_templates SET description = ?, template_data = ? WHERE id = ?')
  const insert = db.prepare(`
    INSERT INTO setup_templates (name, description, template_data, is_system, created_at)
    VALUES (?, ?, ?, 1, datetime('now'))
  `)
  try {
    db.transaction(() => {
      for (const t of templates) {
        const existing = findExisting.get(t.name) as { id: number } | undefined
        if (existing) update.run(t.description, JSON.stringify(t.pulse), existing.id)
        else if (t.since > fromVersion) insert.run(t.name, t.description, JSON.stringify(t.pulse))
      }
      if (fromVersion < 3) upgradeStandardRulesToMonths(db)
    })()
    logger.info('templates', `Built-in setup templates synced (from version ${fromVersion} to ${BUILTIN_TEMPLATES_VERSION})`)
  } catch (err) {
    logger.error('templates', 'Failed to sync setup templates', { error: err instanceof Error ? err.message : String(err) })
    throw err
  }
}

/**
 * Version 2 shipped "Every 6 months" / "Every year" as 182/365 days, which
 * drifts a day or two each cycle. Switch them to calendar months, but only
 * when the rule is still exactly as shipped (never touch a user's edits).
 */
function upgradeStandardRulesToMonths(db: ReturnType<typeof getDb>): void {
  const fix = db.prepare(`
    UPDATE alert_rules SET interval_days = NULL, interval_months = ?, description = ?
    WHERE name = ? AND interval_days = ? AND interval_months IS NULL AND end_of_month = 0 AND thresholds = ?
  `)
  for (const [key, oldDays] of [['semiannual', 182], ['annual', 365]] as const) {
    const r = STANDARD_RULES[key]
    fix.run(r.interval_months, r.description, r.name, oldDays, r.thresholds)
  }
}

