// LetterTemplate is canonically defined in shared/types.ts
import type { LetterTemplate } from '../shared/types'
import { localDateString } from '../shared/dates'
import { BUILTIN_TEMPLATES_VERSION, STANDARD_RULES, builtinSetupTemplates } from './builtin-templates'
import { applyPortableStage, portableStage } from './stage-portable'
import { portableStageSchema, stageColumnOf, stageConfigOf } from '../shared/stages'
import { resolvePlaceholders, type ResolveResult } from './placeholders'
import { canBeRequired } from '../shared/requiredFields'
import { looksLikeBirthColumn } from '../shared/parseDate'
export type { LetterTemplate }

export function getLetterTemplates(): LetterTemplate[] {
  const db = getDb()
  const templates = db.prepare('SELECT * FROM letter_templates ORDER BY is_system DESC, name ASC').all() as LetterTemplate[]

  if (templates.length === 0) {
    const seeded = db.prepare("SELECT 1 FROM app_meta WHERE key = 'letter_templates_seeded'").get()
    if (!seeded && usesHumanServicesWords()) {
      seedLetterTemplates()
      db.prepare("INSERT OR REPLACE INTO app_meta (key, value) VALUES ('letter_templates_seeded', '1')").run()
      return db.prepare('SELECT * FROM letter_templates ORDER BY is_system DESC, name ASC').all() as LetterTemplate[]
    }
  }

  return templates
}

export function createLetterTemplate(name: string, description: string | null, content: string): number {
  const result = getDb().prepare(`
    INSERT INTO letter_templates (name, description, content, is_system, created_at)
    VALUES (?, ?, ?, 0, datetime('now'))
  `).run(name, description ?? null, content)
  return result.lastInsertRowid as number
}

export function updateLetterTemplate(id: number, updates: { name?: string; description?: string | null; content?: string }): void {
  const result = buildSafeSetClause(updates as Record<string, unknown>, ['name', 'description', 'content'])
  if (!result) throw new Error('No valid fields to update')
  getDb().prepare(`UPDATE letter_templates SET ${result.setClause} WHERE id = ?`).run(...result.values, id)
}

export function deleteLetterTemplate(id: number): void {
  getDb().prepare('DELETE FROM letter_templates WHERE id = ?').run(id)
}

/**
 * Generate a letter by filling {{placeholders}} from client data.
 * Returns the filled letter text.
 */
/** Fill a document template for one record (placeholders: src/main/placeholders.ts). */
export function generateLetter(templateId: number, rowId: number, gridId: number): ResolveResult {
  const template = getDb().prepare('SELECT content FROM letter_templates WHERE id = ?').get(templateId) as { content: string } | undefined
  if (!template) throw new Error('Letter template not found')
  return resolvePlaceholders(template.content, rowId, gridId)
}

